import { MeshBasicNodeMaterial, PlaneGeometry, Object3D, Group, Mesh } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { scenePosition, textContent } = config;

  // Create group for the title element
  const group = new Group();

  // --- Background plane ---
  const texture = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');

  // Determine plane aspect ratio from texture naturals (fallback to 512/320 from atlas region)
  const ratio = texture.image ? texture.image.width / texture.image.height : 512 / 320;
  const planeWidth = 2.0;  // arbitrary width, adjust to scene units
  const planeHeight = planeWidth / ratio;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({ map: texture });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // --- Text overlay ---
  // Use headline height from design tokens: 0.34 scene units
  const fontSize = 0.34;

  const textOptions = {
    text: 'Collection',
    fontSize: fontSize,
    fontFamily: 'Lora',           // display serif
    fontWeight: 400,
    color: '#16161d',             // ink color
    textAlign: 'center',
    anchorX: 'center',
    anchorY: 'middle'
  };

  // Assumes ctx.fontAtlas.createText returns a THREE.Mesh or Object3D
  const textMesh = ctx.fontAtlas.createText('Collection', textOptions);
  textMesh.position.set(0, 0, 0.01); // slightly in front of plane
  group.add(textMesh);

  // --- Apply scene placement ---
  if (scenePosition) {
    group.position.copy(scenePosition.position || new THREE.Vector3(0, 3, 0));
    group.rotation.set(
      scenePosition.rotation?._x || 0,
      scenePosition.rotation?._y || 0,
      scenePosition.rotation?._z || 0
    );
    group.scale.set(
      scenePosition.scale?._x || 1,
      scenePosition.scale?._y || 1,
      scenePosition.scale?._z || 1
    );
  } else {
    group.position.set(0, 3, 0);
  }

  // --- No event handlers ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    // Dispose text resources if they expose dispose
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    // Kill any GSAP timelines (none in this element)
  };

  return group;
}
